--
-- Table structure for table `hotel`
--

DROP TABLE IF EXISTS `hotel`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hotel` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '酒店ID',
  `name` varchar(128) NOT NULL COMMENT '酒店名称',
  `address` varchar(255) NOT NULL COMMENT '详细地址',
  `adcode` varchar(12) DEFAULT NULL COMMENT '行政区adcode',
  `latitude` decimal(10,7) DEFAULT NULL COMMENT '纬度',
  `longitude` decimal(10,7) DEFAULT NULL COMMENT '经度',
  `geohash` varchar(12) NOT NULL COMMENT 'geohash',
  `star` tinyint NOT NULL DEFAULT '0' COMMENT '星级 0~5',
  `min_price` decimal(10,3) NOT NULL COMMENT '最低价(元)',
  `audit_status` tinyint NOT NULL DEFAULT '0' COMMENT '审核状态 0待审核 1通过 2拒绝',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '上架状态 1上架 0下架',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_adcode` (`adcode`),
  KEY `idx_geohash` (`geohash`),
  KEY `idx_price` (`min_price`),
  KEY `idx_audit` (`audit_status`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='酒店主表(含审核)';
/*!40101 SET character_set_client = @saved_cs_client */;

