--
-- Table structure for table `hotel_info`
--

DROP TABLE IF EXISTS `hotel_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hotel_info` (
  `hotel_id` bigint NOT NULL COMMENT '酒店ID',
  `name_en` varchar(128) DEFAULT NULL COMMENT '英文名',
  `phone` varchar(32) DEFAULT NULL COMMENT '联系电话',
  `open_date` date DEFAULT NULL COMMENT '开业时间',
  `desc` text COMMENT '酒店简介',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`hotel_id`),
  CONSTRAINT `fk_info_hotel` FOREIGN KEY (`hotel_id`) REFERENCES `hotel` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='酒店扩展信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

