DROP TABLE IF EXISTS `station`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `station` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `cn_name` varchar(255) DEFAULT NULL COMMENT '站点中文名称',
  `en_name` varchar(255) DEFAULT NULL COMMENT '站点英文名称',
  `line_name` varchar(255) DEFAULT NULL COMMENT '线路名称',
  `line_color` varchar(50) DEFAULT NULL COMMENT '线路颜色',
  `city_name` varchar(100) DEFAULT NULL COMMENT '所属城市',
  `lon` varchar(50) DEFAULT NULL COMMENT '经度',
  `lat` varchar(50) DEFAULT NULL COMMENT '纬度',
  `latitude_d` decimal(10,7) DEFAULT NULL COMMENT '数值纬度',
  `longitude_d` decimal(10,7) DEFAULT NULL COMMENT '数值经度',
  `geohash` varchar(12) DEFAULT NULL COMMENT 'geohash',
  PRIMARY KEY (`id`),
  KEY `idx_lat_lng` (`latitude_d`,`longitude_d`)
) ENGINE=InnoDB AUTO_INCREMENT=7975 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
